-- Description: Updates the insight articles with Paulo Cavaleiro's and Paulo Carvalho's Peniche 1984 stories

SET SCHEMA endurancetrio_hub;

-- Update article 1: new featured image and publish date
UPDATE article
SET slug                  = 'paulo-cavaleiro-insight',
    published_date        = '2026-08-15 00:00:00',
    featured_image        = '/img/insights/insights-001-paulo-cavaleiro.jpg',
    featured_image_width  = 1200,
    featured_image_height = 628
WHERE id = 1;

-- Update article 2: new slug, featured image, and publish date
UPDATE article
SET slug                  = 'paulo-carvalho-insight',
    published_date        = '2026-08-15 00:00:00',
    featured_image        = '/img/insights/insights-002-paulo-carvalho.jpg',
    featured_image_width  = 1200,
    featured_image_height = 628
WHERE id = 2;

-- Remove the English translation of article 1
DELETE FROM article_content WHERE id = 2;

-- Update the Portuguese content of article 1 with Paulo Cavaleiro's story
UPDATE article_content
SET locale           = 'pt',
    title            = 'Para além de Peniche: como começou o Triatlo em Portugal',
    subtitle         = NULL,
    intro_text       = '<p>Chamam-me, por vezes, o "pai do Triatlo português".</p>',
    full_text        = '<p>Nunca soube muito bem o que fazer com o título. Primeiro, porque um desporto não nasce de uma pessoa só. Depois, porque, olhando para trás, aquilo que fizemos há mais de 40 anos parece-me ter tido muito menos de paternidade do que de curiosidade, entusiasmo, alguma inconsciência própria dos vinte e poucos anos e uma enorme vontade de pôr coisas a acontecer.</p><p>Mas há uma história para contar. E talvez valha a pena contá-la agora, sobretudo porque a passagem do tempo foi simplificando a origem do Triatlo em Portugal até quase a resumir a uma data e a um lugar: <a href="/pt/events/1984/1/overview"><strong>Peniche, 15 de agosto de 1984</strong></a>.</p><p>Foi aí que se realizou a primeira prova. Mas a história não começou aí.</p><h2>Uns "malucos" no Havai</h2><p>No início dos anos 80, o panorama desportivo era bastante diferente do atual. Não havia ainda esta multiplicação de ultramaratonas, trails, raids, provas de aventura, Ironman e desafios cada vez mais improváveis. O desporto estava muito compartimentado: quem nadava, nadava; quem corria, corria; quem andava de bicicleta, pedalava.</p><p>E eis que começaram a chegar notícias de uns sujeitos que faziam as três coisas seguidas.</p><p>A aventura iniciada por um grupo de norte-americanos no Havai, em 1978, começava a despertar a atenção da comunicação social. Na Europa surgiam também, a partir de 1981, algumas experiências semelhantes e, em 1982, tomei conhecimento do Triatlo de Nice.</p><p>Fiquei imediatamente fascinado.</p><p>Não tanto pela dimensão "extrema" da coisa — expressão que, aliás, ainda não tinha adquirido o significado comercial que hoje possui —, mas pelo <strong>ecletismo</strong>. Havia naquela combinação de natação, ciclismo e corrida um equilíbrio que me atraía. Em vez da especialização absoluta num único gesto, o desafio era adaptar o corpo a três formas diferentes de esforço.</p><p>Comecei então a procurar tudo o que conseguia encontrar sobre aquele novo desporto e a estabelecer contactos com associações e organizadores europeus e norte-americanos.</p><p>Convém recordar que estamos a falar de 1982 e 1983. Não havia Google, email, redes sociais ou sequer Internet disponível para nos facilitar a vida. "Pesquisar" significava revistas, jornais, cartas, telefonemas, contactos pessoais e muita persistência.</p><h2>"Será que alguma estância de Verão…?"</h2><p>Há uma coincidência deliciosa nesta história.</p><p>No número 27 da revista <strong>Spiridon</strong>, de março-abril de 1983, o professor Mário Machado escrevia sobre aquela estranha modalidade em que alguém se propunha nadar 3.800 metros, pedalar 224 quilómetros e, como se ainda não chegasse, correr uma maratona.</p><p>Depois de falar do "Triatlo de Ferro" do Havai e de uma prova de distâncias menores em Long Beach, terminava com uma pergunta quase profética:</p><blockquote>"Será que alguma estância de Verão aparecerá, dentro em pouco, com a modalidade em Portugal?"</blockquote><p>Não foi propriamente uma estância de verão. Mas não andou longe.</p><p>Nesse mesmo ano aproveitei uma viagem a Nova Iorque para visitar o <a href="https://www.nyrr.org/" target="_blank" rel="noopener">New York Road Runners Club</a>, levando referências do Mário Machado. Queria perceber melhor o que se estava a passar com o Triatlo nos Estados Unidos e como começava a organizar-se internacionalmente.</p><p>A <a href="https://www.nyrr.org/" target="_blank" rel="noopener">Triathlon USA</a> tinha sido criada em 1982 e estava precisamente a lançar, em 1983, o seu primeiro campeonato de curta distância.</p><p>Regressei ainda mais convencido de que tínhamos de fazer aquilo em Portugal.</p><p>E pedi ajuda ao Mário.</p><p>Ele conhecia organizadores de provas por todo o país, sobretudo municípios, e pedi-lhe que estivesse atento a alguém suficientemente disponível — ou suficientemente aventureiro — para aceitar organizar um primeiro Triatlo.</p><h2>E então apareceu Peniche</h2><p>Foi assim que Peniche entrou na história.</p><p>Mário Machado soube que a Câmara Municipal, através do responsável pelo sector do Desporto, <a href="/pt/athletes/22"><strong>Nuno Belo</strong></a>, estava a preparar para as festas da cidade de agosto de 1984 uma competição destinada essencialmente aos pescadores locais.</p><p>A ideia era curiosa: combinar <strong>remo em barcos de pescadores, ciclismo e corrida a pé</strong>.</p><p>Não era Triatlo, portanto. E Nuno Belo não tinha conhecimento do movimento internacional que estava então a desenvolver-se em torno da modalidade.</p><p>Mas estava lá quase tudo o que era necessário: a ideia de combinar diferentes formas de esforço, um organizador disponível e, sobretudo, vontade de fazer qualquer coisa nova.</p><p>Mário Machado pôs-nos em contacto.</p><p>Na primeira reunião expliquei ao Nuno o que era o Triatlo, mostrei-lhe o que estava a acontecer noutros países e disse-lhe que a introdução da modalidade em Portugal estava iminente: eu procurava ativamente um lugar para realizar a primeira prova e já existiam pessoas interessadas.</p><p>Ele percebeu imediatamente a oportunidade.</p><p>Em meados de junho de 1984, a escassos dois meses da data prevista, Peniche deu luz verde.</p><p>O remo saiu, entrou a natação e começou uma pequena corrida contra o tempo para organizar o primeiro Triatlo português.</p><p>Nuno Belo fez o trabalho essencial no terreno. Eu passei-lhe toda a informação que tinha acumulado sobre a modalidade e dei o apoio possível à organização.</p><p>No dia <strong>15 de agosto de 1984</strong>, trinta pioneiros alinharam na Ribeira, em Peniche, para 400 metros de natação, cerca de 17 quilómetros de bicicleta e 8 quilómetros de corrida.</p><p>Chegaram 28 ao fim.</p><p>Ganhou <a href="/pt/athletes/1"><strong>Paulo Carvalho</strong></a>, atleta do Queluz, que nessa altura ainda não era triatleta — pela simples razão de que praticamente ninguém em Portugal o podia ser.</p><p>Tínhamos finalmente um Triatlo.</p><p>Por isso, quando se diz que o Triatlo português "nasceu em Peniche", a frase é verdadeira se estivermos a falar da <strong>primeira prova</strong>. Mas não será inteiramente correta se com isso quisermos dizer que tudo começou ali, espontaneamente.</p><p>Peniche foi a concretização de um processo que já vinha de 1982-83.</p><p>E, ironicamente, enquanto fazíamos nascer o Triatlo português, a Europa também se organizava: apenas <strong>dois dias depois de Peniche, em 17 de agosto de 1984</strong>, representantes de dez países reuniam-se em Avignon para constituir a <a href="https://europe.triathlon.org/" target="_blank" rel="noopener"><strong>European Triathlon Union</strong></a>.</p><p>Não estivemos lá.</p><p>Tínhamos uma boa desculpa.</p><h2>De Peniche para Cascais — e para o Rio</h2><p>A partir daí as coisas aceleraram.</p><p>Ainda em 1984, o diretor do <a href="https://www.dn.pt/" target="_blank" rel="noopener"><strong>Diário de Notícias</strong></a> teve conhecimento da experiência de Peniche e contactou-me. A marca francesa <strong>Le Coq Sportif</strong> pretendia apoiar o Triatlo em Portugal e integrá-lo num circuito internacional, e o grupo editorial queria associar-se à organização de uma grande prova já no ano seguinte.</p><p>Começou assim a minha colaboração com o Diário de Notícias.</p><p>O resultado foi o <a href="/pt/events/1985/2/overview"><strong>1º Triatlo Internacional de Cascais, em 29 de junho de 1985</strong></a>, ao qual se seguiram várias edições.</p><p>E de repente aquilo que pouco tempo antes parecia uma extravagância de uns quantos "malucos" começava a ganhar dimensão.</p><p>Em agosto de 1985 estava já a inscrever <strong>Paulo Carvalho</strong>, <strong>José Mariz</strong> e <strong>Carlos Carmino</strong> no Triatlo Internacional do Rio de Janeiro, a realizar em setembro. Formavam aquilo a que poderemos chamar, com alguma liberdade histórica, a nossa primeira seleção nacional oficiosa. A participação fazia parte do prémio pelos resultados obtidos em Cascais.</p><p>Ainda não tínhamos federação.</p><p>Mas já tínhamos "seleção".</p><h2>Uma revista para um desporto que ainda estava a nascer</h2><p>Em março de 1986 meti-me noutra aventura: publicar uma revista exclusivamente dedicada à modalidade.</p><p>Chamava-se simplesmente <strong>TRIATLO – Desporto para viver</strong>.</p><p>Foi um esforço pessoal considerável, tornado possível pelo apoio de várias pessoas, entre as quais o designer <strong>Alfredo de Sousa</strong>, e pelo suporte do <em>Diário de Notícias</em> na produção.</p><p>No editorial do primeiro número escrevemos que o Triatlo nos atraía pela conjugação de "<strong>PRAZER e VONTADE</strong>" e pela constante "<strong>DESCOBERTA e CONQUISTA</strong>" de nós próprios, de novos espaços e de capacidades insuspeitadas.</p><p>Mais de quatro décadas depois, continuo a achar que era uma descrição bastante razoável.</p><p>A revista pretendia informar, naturalmente, mas sobretudo incentivar a ação, a iniciativa e a participação.</p><p>Precisávamos agora de transformar aquele movimento de provas, atletas e entusiastas numa organização.</p><h2>Os "carolas" do Estrela do Mar</h2><div class="card"><div class="card-image"><figure class="image"><img src="/img/insights/insights-001-cartao-apt-numero-um.png" alt="Cartão Número 1 da APT"/></figure></div></div><p>A revista acabou por funcionar também como montra e ponto de encontro do pequeno mundo do Triatlo português.</p><p>Comecei a incentivar a criação de uma associação nacional e convenci <strong>Carlos Raimundo</strong>, então dirigente superior da Câmara Municipal de Oeiras, a assumir a presidência.</p><p>A <strong>Associação Portuguesa de Triatlo (APT)</strong> foi constituída por escritura em 26 de maio de 1987.</p><p>Coube-me o número de associado <strong>número 1</strong>, que guardo sobretudo como recordação daquela aventura coletiva.</p><p>Porque a imagem mais fiel dos primórdios do Triatlo português talvez não seja uma grande sala de reuniões ou um gabinete federativo.</p><p>É um armazém.</p><p>Mais precisamente, o armazém do café-restaurante <strong>Estrela do Mar, em Carcavelos</strong>, propriedade de <strong>João Neves Almeida</strong>, um dos grandes benfeitores da modalidade nesses primeiros tempos.</p><p>Era ali que se juntava aquele grupo de "carolas".</p><p>Sem grandes meios. Sem estruturas profissionais. Provavelmente com reuniões menos formais do que recomendaria qualquer manual de gestão desportiva.</p><p>Mas com uma vontade enorme de fazer crescer o Triatlo.</p><h2>Com as poupanças até à Finlândia</h2><div class="card"><div class="card-image"><figure class="image"><img src="/img/insights/insights-001-europe-triathlon-1987-conference.jpg" alt="Congresso da European Triathlon de 1987"/></figure></div></div><p>Entretanto eu continuava a corresponder-me com os dirigentes europeus que contactava desde 1983.</p><p>Em 1987 decidi dar mais um passo.</p><p>Juntei as minhas poupanças e fui até <strong>Joroinen, na Finlândia</strong>, onde, paralelamente ao Campeonato Europeu de Longa Distância, se realizaria um congresso da jovem European Triathlon Union.</p><p>Levava uma ambição na bagagem: apresentar a candidatura portuguesa à organização, em Cascais, do <a href="/pt/events/1989/51/overview"><strong>Campeonato Europeu de Triatlo de Curta Distância de 1989</strong></a>.</p><p>Foi também aí que encontrei pessoalmente, pela primeira vez, homens como <strong>Didier Lehénaff</strong>, <strong>Joop van Zanten</strong>, <strong>Con O''Callaghan</strong> e <strong>Václav Vítovec</strong>, entre outros dirigentes europeus com quem há anos trocava correspondência.</p><p>É curioso pensar nisso hoje.</p><p>Portugal tinha realizado o seu primeiro Triatlo apenas três anos antes e nós já estávamos numa reunião europeia a propor organizar um Campeonato da Europa.</p><p>Talvez fosse ousadia.</p><p>Talvez inconsciência.</p><p>Naquela idade, felizmente, as duas coisas confundem-se com alguma facilidade.</p><h2>Finalmente, uma Federação</h2><div class="card"><div class="card-image"><figure class="image"><img src="/img/insights/insights-001-cartao-ftp-numero-um.png" alt="Cartão Número 1 da FTP"/></figure></div></div><p>A <a href="https://www.federacao-triatlo.pt/ftp2015/a-federacao/apresentacao-ftp/" target="_blank" rel="noopener"><strong>Federação de Triatlo de Portugal</strong></a> constituiu-se em <strong>16 de outubro de 1989</strong>.</p><p>Nesse mesmo ano havia já um calendário com <strong>22 provas de Triatlo</strong>, incluindo uma de média distância, que reuniu cerca de 40 participantes.</p><p>Em cinco anos tínhamos passado de <a href="/pt/events/1984/1/results/1">30 pioneiros numa praia de Peniche</a> para uma modalidade com calendário nacional, associação, federação e relações internacionais estabelecidas.</p><p>E Cascais recebeu finalmente o Campeonato Europeu cuja candidatura eu levara à Finlândia.</p><p>A sua concretização deve muito ao empenho de <strong>Jorge Damas</strong>, que viria infelizmente a falecer demasiado cedo e cuja intervenção merece ser recordada.</p><p>Com a criação da Federação considerei, nessa altura, que a minha missão estava cumprida.</p><p>Tinha outras exigências profissionais e pareceu-me que chegara o momento de ficar apenas disponível para ajudar quando fosse necessário.</p><p>A modalidade já conseguia caminhar pelas próprias pernas.</p><p>Ou nadar, pedalar e correr por elas.</p><p>Não correu tudo tão tranquilamente quanto eu esperava. A primeira presidência da Federação mergulhou-a numa grave instabilidade e acabou por haver eleições antecipadas. Em setembro de 1991 fui empurrado — não encontro palavra muito melhor — para assumir a presidência.</p><p>Foi uma função que deixei logo que as circunstâncias o permitiram.</p><p>Mais tarde, em 1995, <strong>Adriano Cunha</strong> assumiria a presidência e faria o importante trabalho de reformulação e consolidação da estrutura federativa.</p><p>A partir daí começa outra história — muito mais conhecida e que já não precisa de mim para ser contada.</p><p>Em 1994, o Triatlo foi admitido no programa dos Jogos Olímpicos. Em Sydney, no ano 2000, os primeiros triatletas olímpicos mergulharam finalmente na água.</p><p>Para quem, menos de vinte anos antes, andara a enviar cartas para vários cantos do mundo tentando perceber como funcionava aquele estranho desporto, confesso que foi bonito assistir.</p><h2>Afinal, quem foi o "pai"?</h2><p>Em <strong>8 de março de 1997</strong>, a Assembleia Geral da Federação atribuiu-me o <strong>Diploma de Associado Honorário</strong>.</p><p>É uma distinção que naturalmente me honra.</p><p>Quanto à outra, a de "pai do Triatlo português", continuo a recebê-la com alguma reserva e um sorriso.</p><p>Se alguma coisa fiz de importante, talvez tenha sido simplesmente <strong>ver cedo uma ideia em que valia a pena acreditar e conseguir juntar pessoas à sua volta</strong>.</p><p>Sem Mário Machado talvez não tivesse aparecido Peniche naquele momento.</p><p>Sem Nuno Belo não teria havido aquele 15 de agosto de 1984.</p><p>Sem os responsáveis do <em>Diário de Notícias</em>, Cascais dificilmente teria adquirido a dimensão que adquiriu.</p><p>Sem Alfredo de Sousa e todos os que colaboraram e patrocinaram a revista <em>Triatlo</em>, não teríamos tido aquela extraordinária ferramenta de divulgação e agregação.</p><p>Sem Carlos Raimundo, João Neves Almeida, Nelson Laranjeira, Luis Ascenso e os restantes "carolas" da APT, não se teria criado a primeira estrutura organizada.</p><p>Sem Jorge Damas, Adriano Cunha, Artur Parreira e tantos outros que não consigo aqui enumerar, vários passos seguintes não teriam sido possíveis.</p><p>Enfim, sem a <strong>Dora Pinto</strong>, minha companheira desde antes desses primeiros tempos e minha esposa desde que se sagrou a primeira campeã nacional de Triatlo, provavelmente muito disto também não teria sido possível. Ela não se limitou a aceitar esta aventura: fez dela também a sua e acompanhou com disponibilidade, esforço – e algum pânico, por vezes – praticamente todas as iniciativas em que fui comprometendo os nossos recursos ao longo daqueles anos.</p><p>E, acima de tudo, sem aqueles primeiros atletas, e respectivas famílias, que aceitaram mergulhar, pegar numa bicicleta e depois sair a correr — quando quase ninguém sabia muito bem por que raio alguém quereria fazer três desportos seguidos — não haveria modalidade nenhuma para organizar.</p><p>Talvez seja essa a parte da história de que mais gosto.</p><p>Começámos sem saber exatamente onde aquilo nos levaria.</p><p>Não havia carreiras a construir, lugares a conquistar ou estruturas onde instalar alguém. Na verdade, <strong>a estrutura ainda nem existia</strong>.</p><p>Havia apenas uma ideia nova, um grupo de pessoas disponíveis e o prazer quase infantil de construir qualquer coisa que achávamos que valia a pena.</p><p>No editorial da revista <em>TRIATLO</em>, em março de 1986, escrevi que aquele desporto propunha "um novo enquadramento do indivíduo na sua prática física".</p><p>Quase quinze anos depois, num artigo publicado quando o Triatlo se preparava para chegar aos Jogos Olímpicos de Sydney, resumi a questão de maneira bastante menos solene, da mesma forma que o jornalista João Alves da Costa do jornal A Bola já tinha esclarecido a propósito do <a href="/pt/events/1986/5/overview">Triatlo de Cascais de 1986</a>:</p><blockquote>"Basta provar para gostar!"</blockquote><p>Pensando bem, talvez não tenha encontrado entretanto definição melhor.</p><p>E foi mais ou menos assim que tudo começou.</p>',
    meta_title       = 'Para além de Peniche: como começou o Triatlo em Portugal',
    meta_description = 'Do fascínio pelos anos 80 ao primeiro Triatlo em Peniche, em 15 de agosto de 1984. Paulo Cavaleiro conta como nasceu o Triatlo em Portugal.'
WHERE id = 1;

-- Update the Portuguese content of article 2
UPDATE article_content
SET title            = 'Como um país "pobre" impactou o meu percurso desportivo - Peniche 1984',
    subtitle         = NULL,
    intro_text       = '<p>Se me perguntarem qual foi sempre o meu maior sonho, a resposta é simples e imediata: a natação de competição.</p>',
    full_text        = '<p>Tudo começou em 1972. Eu tinha 11 anos, vivia em Luanda e fiquei absolutamente hipnotizado ao ver o lendário Mark Spitz nadar mariposa nos Jogos Olímpicos de Munique. Olhei para aquilo fascinado, a pensar: "Quem me dera nadar assim". A minha grande referência estava ali e, desde essa altura, a natação de competição — em particular a técnica de mariposa — tornou-se a minha grande paixão.</p><p>Mas a vida real não me permitiu desenvolver esse sonho como desejava. Em finais de 1974, quando regressei a Azeitão, encontrei um país empobrecido, sem piscinas aquecidas na minha área de residência (Azeitão) e de estudos (Setúbal). Sem piscina de inverno, era impossível treinar natação a sério entre outubro e abril. Para manter a forma física durante os meses mais frios, se não dava para nadar, corria; e, quando me fartava de correr, pedalava até à Figueirinha, onde matava saudades da água nadando no mar até "gelar" (10 a 15 minutos).</p><p>Sem eu saber, a vida estava a desenhar-me um caminho alternativo.</p><p>Representei a natação da SFUAP de 1976 a 1979. Em 1979 fui para o Instituto Superior Técnico (IST) estudar e passei a treinar natação todo o ano na piscina do IST, em representação do Sporting. Em 1981, tive de me concentrar em terminar o curso e acabei por abandonar a natação de competição para me dedicar por completo aos estudos. Mas a paixão pelo desporto continuava lá: eu já fazia as viagens entre casa (em Azeitão) e o IST (em Lisboa) de bicicleta; além disso, corria quase diariamente em Azeitão e, de vez em quando, matava saudades dando umas braçadas na piscina do IST e outras no mar da Figueirinha.</p><p>E foi precisamente aí, em 1984, na piscina do IST, que encontrei o <a href="/pt/athletes/4">Paulo Cavaleiro</a>, que me desafiou:</p><blockquote>"Tu ias gostar mesmo era de fazer um Triatlo! Sabes que vai ser realizado o primeiro em Portugal, em Peniche, este verão?"</blockquote><p>Olhei para ele sem perceber bem a palavra:</p><blockquote>"Ti quê? Parece que disseste Teatro?"</blockquote><blockquote>"TRI-A-TLO. Nadar, pedalar e correr. Tu estás claramente bem ambientado a todas as três modalidades. Era uma boa experiência para ti."</blockquote><p>Foi aí que percebi que, por mais que o meu sonho original fosse a natação pura, os últimos anos tinham-me encaminhado naturalmente para a nova modalidade.</p><p>Aceitei o desafio e, no dia 15 de agosto de 1984, lá estava eu com os meus óculos de natação, uma "pasteleira" pesada e velha e uns ténis básicos para experimentar o <a href="/pt/events/1984/1/overview">primeiro triatlo de Portugal, em Peniche</a>.</p><p>O resultado foi uma aventura simultaneamente excitante, sofrida e divertida. Saí gelado das águas de Peniche, atirei-me para a bicicleta, sofri nas subidas da costa a arrastar aquela "pasteleira" e rebentei de vez a correr pelas mesmas encostas e pelas ruas da cidade.</p><p><a href="/pt/events/1984/1/results/1">Cortei a meta</a> de rastos, mas muito entusiasmado e feliz com o resultado. O meu sonho de miúdo em torno da mariposa e de Mark Spitz nunca desapareceu, mas ganhei uma nova motivação para competir num desporto tão desafiante. A minha natação ganhou duas rodas e um par de ténis e, assim, continuei a divertir-me a competir por mais uns anos.</p>',
    meta_title       = 'Peniche 1984: o primeiro triatlo de Portugal na primeira pessoa',
    meta_description = 'Paulo Carvalho tinha um sonho: nadar como Mark Spitz. Em 15 de agosto de 1984, viveu o primeiro triatlo de Portugal, em Peniche, e nunca mais parou de competir.'
WHERE id = 3;

-- Insert the English content of article 2
INSERT INTO
  article_content (id, article_id, locale, title, subtitle, intro_text, full_text, meta_title, meta_description, version, created_at, updated_at)
VALUES
  (
    4,
    2,
    'en',
    'How a "poor" country shaped my athletic journey - Peniche 1984',
    NULL,
    '<p>If anyone asks me what my greatest dream has always been, the answer is simple and immediate: competitive swimming.</p>',
    '<p>It all started in 1972. I was 11 years old, living in Luanda, and got completely hypnotized watching the legendary Mark Spitz butterfly swimming at the Munich Olympic Games. I looked at that, fascinated, thinking: "I wish I could swim like that." My great role model was right there, and from that moment on, competitive swimming — particularly the butterfly stroke — became my lifelong passion.</p><p>But real life got in the way and did not allow me to pursue that dream the way I wanted. In late 1974, when I returned to Azeitão, I found an impoverished country, with no heated swimming pools where I lived (Azeitão) and studied (Setúbal). Without an indoor pool, it was impossible to properly train swimming between October and April. To stay in shape during the colder months, when swimming wasn''t possible, I ran; and when I got tired of running, I cycled to Figueirinha beach, where I satisfied my longing for the water by swimming in the sea until I was "freezing" (10 to 15 minutes).</p><p>Without knowing it, life was charting an alternative path for me.</p><p>I represented SFUAP''s swimming team from 1976 to 1979. In 1979, I went to study at the Instituto Superior Técnico (IST) and began training swimming year-round at the IST pool, while competing for Sporting. In 1981, I focused on finishing my degree and ended up quitting competitive swimming to dedicate myself fully to studies. But the passion for sport was still there: I was already commuting by bicycle between home (in Azeitão) and IST (in Lisbon); on top of that, I ran almost daily in Azeitão and, from time to time, satisfied my craving for the water by swimming a few laps in the IST pool and in the sea at Figueirinha.</p><p>And it was precisely there, in 1984, at the IST pool, that I came across <a href="/en/athletes/4">Paulo Cavaleiro</a>, who challenged me:</p><blockquote>"What you''d really enjoy is doing a Triathlon! Did you know the first one in Portugal is happening this summer, in Peniche?"</blockquote><p>I looked at him, not quite understanding a word:</p><blockquote>"Tri-what? Sounds like you said Theater?"</blockquote><blockquote>"TRI-A-THLON. Swim, bike, and run. You are clearly well-adapted to all three disciplines. It would be a great experience for you."</blockquote><p>That was when I realized that, as much as my original dream was pure swimming, the past few years had naturally led me toward this new sport.</p><p>I accepted the challenge, and on August 15th, 1984, there I was in Peniche, with my swimming goggles, a heavy, old utility bike (pasteleira), and some basic running shoes ready to try out <a href="/en/events/1984/1/overview">Portugal''s first triathlon</a>.</p><p>The result was an adventure that was simultaneously exciting, grueling, and fun. I came out of the water frozen stiff, threw myself onto the bicycle, suffered on the coastal climbs dragging the pasteleira, before blowing up running along those same slopes and through town.</p><p><a href="/en/events/1984/1/results/1">I crossed the finish line</a> shattered, but very enthusiastic and happy with the outcome. My childhood dream of butterfly swimming and Mark Spitz never disappeared, but I had found a new motivation to enjoy competing in a sport as challenging and exciting as triathlon. My swimming gained two wheels and a pair of running shoes, and I continued to enjoy competing for a few more years.</p>',
    'Peniche 1984: Portugal''s first triathlon in the first person',
    'Paulo Carvalho''s dream was to swim like Mark Spitz. On August 15, 1984, he took part in Portugal''s first triathlon in Peniche and never looked back.',
    0,
    NOW(),
    NULL
  );

